<?php
require_once __DIR__.'/../../includes/auth.php';require_once __DIR__.'/product_helpers.php';
$q=trim($_GET['q']??'');$status=$_GET['status']??'';$info=trim($_GET['info']??'');$where=[];$params=[];
if($q!==''){$where[]='(product_name LIKE :q_name OR product_code LIKE :q_code OR barcode_code LIKE :q_barcode OR category LIKE :q_category)';$queryValue='%'.$q.'%';$params[':q_name']=$queryValue;$params[':q_code']=$queryValue;$params[':q_barcode']=$queryValue;$params[':q_category']=$queryValue;}
if(in_array($status,['active','inactive'],true)){$where[]='status=:status';$params[':status']=$status;}
$sql='SELECT * FROM products'.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY product_name';$s=$pdo->prepare($sql);$s->execute($params);$products=$s->fetchAll(PDO::FETCH_ASSOC);
$summary=$pdo->query("SELECT COUNT(*) total,SUM(status='active') active_total,COALESCE(SUM(CASE WHEN track_stock=1 THEN stock ELSE 0 END),0) stock_total,COALESCE(SUM(CASE WHEN track_stock=1 THEN stock*base_price ELSE 0 END),0) stock_value FROM products")->fetch(PDO::FETCH_ASSOC);
$pageTitle='Produk - Nukari';require_once __DIR__.'/../../includes/header.php';require_once __DIR__.'/../../includes/sidebar.php';require_once __DIR__.'/_style.php';?>
<main class="main-content"><div class="container-fluid product-page py-3"><?php require __DIR__.'/_nav.php';?><?php if($info!==''):?><div class="alert alert-info rounded-4"><?=product_safe($info);?></div><?php endif;?><div class="page-header d-flex justify-content-between align-items-center flex-wrap gap-3"><div><h1 class="fw-bold mb-1">Produk Jadi</h1><p class="text-muted mb-0">Kelola produk, harga dasar, harga jual, dan stok yang tampil di POS.</p></div><a href="add.php" class="btn btn-nukari"><i class="bi bi-plus-lg me-1"></i> Tambah Produk</a></div>
<div class="row g-3 mb-4"><div class="col-md-3"><div class="kpi-card"><small>Total Produk</small><h3><?=(int)$summary['total'];?></h3></div></div><div class="col-md-3"><div class="kpi-card"><small>Produk Aktif</small><h3><?=(int)$summary['active_total'];?></h3></div></div><div class="col-md-3"><div class="kpi-card"><small>Total Stok</small><h3><?=product_num($summary['stock_total']);?></h3></div></div><div class="col-md-3"><div class="kpi-card"><small>Nilai Harga Dasar</small><h3><?=product_money($summary['stock_value']);?></h3></div></div></div>
<div class="product-card"><div class="card-body"><form class="row g-2 mb-3"><div class="col-md-6"><input name="q" class="form-control" value="<?=product_safe($q);?>" placeholder="Cari nama, kode, barcode, atau kategori"></div><div class="col-md-3"><select name="status" class="form-select"><option value="">Semua status</option><option value="active" <?=$status==='active'?'selected':'';?>>Active</option><option value="inactive" <?=$status==='inactive'?'selected':'';?>>Inactive</option></select></div><div class="col-md-3"><button class="btn btn-success">Filter</button> <a href="simple.php" class="btn btn-light">Reset</a></div></form><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Produk</th><th>Kategori</th><th>Harga Dasar</th><th>Harga Jual</th><th>Stok</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($products as $p):?><tr><td><div class="d-flex align-items-center gap-2"><?php if($p['photo']):?><img src="<?=base_url($p['photo']);?>" alt="" style="width:46px;height:46px;object-fit:cover;border-radius:12px"><?php endif;?><div><b><?=product_safe($p['product_name']);?></b><div class="small text-muted"><?=product_safe($p['product_code']);?> · <?=product_safe($p['barcode_code']);?></div></div></div></td><td><?=product_safe($p['category']);?></td><td><?=product_money($p['base_price']);?></td><td class="fw-bold text-success"><?=product_money($p['selling_price']);?></td><td><?=($p['track_stock']??1)?product_num($p['stock']).' '.product_safe($p['unit']):'<span class="badge bg-info">Tanpa kontrol</span>';?></td><td><span class="badge <?=$p['status']==='active'?'bg-success':'bg-secondary';?>"><?=product_safe($p['status']);?></span></td><td><a class="btn btn-sm btn-outline-primary" href="edit.php?id=<?=(int)$p['id'];?>">Edit</a></td></tr><?php endforeach;?><?php if(!$products):?><tr><td colspan="7" class="text-center text-muted py-4">Belum ada produk.</td></tr><?php endif;?></tbody></table></div></div></div></div></main><?php require_once __DIR__.'/../../includes/footer.php';?>
